import { createElement, type ComponentType, useCallback, useEffect, useMemo, useRef, useState } from "react";
import { Box } from "@/shared/ui/layout/Box";
import { Row } from "@/shared/ui/layout/Row";
import { Stack } from "@/shared/ui/layout/Stack";
import { Text } from "@/shared/ui/typography/Text";
import { Button } from "@/shared/ui/controls/Button";

type StructureName = "array" | "matrix" | "graph" | "linked-list" | "tree" | "table" | "stack" | "scalar";
interface FrameMeta { loc?: { start: number; end: number; line: number } }
interface StructureFrame extends FrameMeta { structure: StructureName; [k: string]: unknown }
interface PanelsFrame extends FrameMeta { panels: Record<string, StructureFrame> }
type Frame = StructureFrame | PanelsFrame;
function isPanelsFrame(frame: Frame): frame is PanelsFrame {
  return "panels" in frame;
}
function normalizeFrame(frame: Frame): Record<string, StructureFrame> {
  return isPanelsFrame(frame) ? frame.panels : { main: frame as StructureFrame };
}

type StructureRenderer = ComponentType<{ frame: StructureFrame }>;
type RendererRegistry = { [S in StructureName]?: StructureRenderer };
const fallbackRenderer: StructureRenderer = ({ frame }) => (
  <Stack gap={4} className="trace-fallback">
    <Text as="span" mono size={10} tone="dim" style={{ textTransform: "uppercase", letterSpacing: ".06em" }}>{frame.structure}</Text>
    <Box as="pre" className="trace-fallback-json mono">
      {JSON.stringify(frame, null, 2)}
    </Box>
  </Stack>
);
function resolveRenderer(registry: RendererRegistry, structure: StructureName): StructureRenderer {
  return (registry[structure] as StructureRenderer | undefined) ?? fallbackRenderer;
}

const DEFAULT_BUFFER_SIZE = 500;
interface TraceStream {
  current(): Frame | null;
  next(): Frame | null;
  seek(i: number): Frame | null;
  index(): number;
  atEnd(): boolean;
}
class Ring {
  private buf: (Frame | undefined)[];
  private start = 0;
  private count = 0;
  constructor(readonly capacity: number) {
    this.buf = new Array(capacity);
  }
  push(frame: Frame): void {
    this.buf[(this.start + this.count) % this.capacity] = frame;
    if (this.count < this.capacity) this.count++;
    else this.start++;
  }
  get firstIndex(): number { return this.start; }
  get nextIndex(): number { return this.start + this.count; }
  has(i: number): boolean { return i >= this.start && i < this.start + this.count; }
  get(i: number): Frame | undefined { return this.has(i) ? this.buf[i % this.capacity] : undefined; }
  clear(): void { this.start = 0; this.count = 0; }
}
function makeTraceStream(factory: () => Generator<Frame>, opts: { bufferSize?: number } = {}): TraceStream {
  const capacity = Math.max(1, Math.floor(opts.bufferSize ?? DEFAULT_BUFFER_SIZE));
  const ring = new Ring(capacity);
  let gen = factory();
  let cursor = -1;
  let exhausted = false;

  function pull(): Frame | null {
    if (exhausted) return null;
    const r = gen.next();
    if (r.done) { exhausted = true; return null; }
    ring.push(r.value);
    return r.value;
  }
  function replayTo(i: number): Frame | null {
    gen = factory();
    ring.clear();
    exhausted = false;
    for (let k = 0; k <= i; k++) { if (pull() == null) break; }
    cursor = ring.nextIndex - 1;
    return current();
  }
  function current(): Frame | null { return cursor < 0 ? null : ring.get(cursor) ?? null; }
  function next(): Frame | null {
    const target = cursor + 1;
    if (target < ring.nextIndex) { cursor = target; return current(); }
    const frame = pull();
    if (frame == null) return null;
    cursor = target;
    return frame;
  }
  function seek(i: number): Frame | null {
    if (i < 0) { cursor = -1; return null; }
    if (ring.has(i)) { cursor = i; return current(); }
    if (i < ring.firstIndex) return replayTo(i);
    while (ring.nextIndex <= i && !exhausted) pull();
    cursor = Math.min(i, ring.nextIndex - 1);
    return current();
  }
  return { current, next, seek, index: () => cursor, atEnd: () => exhausted && cursor === ring.nextIndex - 1 };
}

const RESUME_MS = 2500;
export interface TracePlayerProps {
  /** Produces a fresh trace generator from the algorithm's fixed input. MEMOIZE this at the call site
   *  (a stable identity) — a new factory rebuilds the stream (a fresh replay from frame 0). */
  factory: () => Generator<Frame>;
  /** The per-structure renderers to dispatch panels to. Omitted/partial → the fallback renderer covers
   *  any unregistered structure. */
  renderers?: RendererRegistry;
  bufferSize?: number;
  /** Playback speed — frames per second. Default 4. */
  fps?: number;
  autoPlay?: boolean;
  loop?: boolean;
  controls?: boolean;
  source?: string;
}
function demoFactory(): Generator<Frame> {
  const data = [5, 3, 8, 1, 9, 2];
  function* gen(): Generator<Frame> {
    for (let i = 0; i < data.length - 1; i++) {
      yield { structure: "array", data, ops: [{ op: "compare", at: [i, i + 1] }] } as StructureFrame;
      if (data[i] > data[i + 1]) {
        [data[i], data[i + 1]] = [data[i + 1], data[i]];
        yield { structure: "array", data: [...data], ops: [{ op: "swap", at: [i, i + 1] }] } as StructureFrame;
      }
    }
  }
  return gen();
}
function PanelView({ name, frame, renderers }: { name: string; frame: StructureFrame; renderers: RendererRegistry }) {
  const renderer = resolveRenderer(renderers, frame.structure);
  return (
    <Stack gap={6} className="trace-panel">
      <Text as="span" mono size={10} tone="dim" style={{ textTransform: "uppercase", letterSpacing: ".06em" }}>
        {name} · {frame.structure}
      </Text>
      {createElement(renderer, { frame })}
    </Stack>
  );
}
export function TracePlayer({ factory = demoFactory, renderers = {}, bufferSize, fps = 4, autoPlay = true, loop = true, controls = true, source }: TracePlayerProps) {
  const stream = useMemo(() => makeTraceStream(factory, { bufferSize }), [factory, bufferSize]);
  const [frame, setFrame] = useState<Frame | null>(null);
  const [index, setIndex] = useState(-1);
  const [maxIndex, setMaxIndex] = useState(-1);
  const [playing, setPlaying] = useState(false);

  const sync = useCallback(() => {
    const i = stream.index();
    setIndex(i);
    setFrame(stream.current());
    setMaxIndex((m) => Math.max(m, i));
  }, [stream]);

  useEffect(() => {
    stream.seek(0);
    sync();
    setPlaying(autoPlay);
  }, [stream, sync, autoPlay]);

  useEffect(() => {
    if (!playing) return;
    const id = setInterval(() => {
      const f = stream.next();
      if (f == null) {
        if (loop) { stream.seek(0); sync(); } else { sync(); setPlaying(false); }
      } else {
        sync();
      }
    }, Math.max(1, Math.round(1000 / fps)));
    return () => clearInterval(id);
  }, [playing, stream, sync, fps, loop]);

  const resumeTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const clearResume = useCallback(() => {
    if (resumeTimer.current) { clearTimeout(resumeTimer.current); resumeTimer.current = null; }
  }, []);
  const pauseThenResume = useCallback(() => {
    setPlaying(false);
    clearResume();
    if (loop) resumeTimer.current = setTimeout(() => setPlaying(true), RESUME_MS);
  }, [loop, clearResume]);
  useEffect(() => clearResume, [clearResume]);

  const stepForward = useCallback(() => {
    pauseThenResume();
    if (stream.next() == null) stream.seek(0);
    sync();
  }, [stream, sync, pauseThenResume]);
  const stepBack = useCallback(() => {
    pauseThenResume();
    stream.seek(Math.max(0, stream.index() - 1));
    sync();
  }, [stream, sync, pauseThenResume]);

  const panels = frame ? normalizeFrame(frame) : {};
  const entries = Object.entries(panels);
  const knownSteps = Math.max(0, maxIndex);

  const panelsRow = (
    <Row gap={12} wrap className="trace-panels">
      {entries.length === 0 ? (
        <Text size={12} tone="muted">No frames.</Text>
      ) : (
        entries.map(([name, panel]) => <PanelView key={name} name={name} frame={panel} renderers={renderers} />)
      )}
    </Row>
  );

  return (
    <Stack gap={12} className="trace-player">
      {source ? (
        <Row gap={12} className="trace-split">
          <Box className="trace-split-viz">{panelsRow}</Box>
        </Row>
      ) : (
        panelsRow
      )}

      {controls && (
        <Row gap={8} align="center" className="trace-controls">
          <Button variant="ghost" size="sm" aria-label="Step back" onClick={stepBack} disabled={index <= 0}>
            ‹ Step
          </Button>
          <Button variant="ghost" size="sm" aria-label="Step forward" onClick={stepForward}>
            Step ›
          </Button>
          <Text mono size={11} tone="dim">
            step {index < 0 ? "—" : index + 1}{knownSteps > 0 ? ` / ${knownSteps + 1}` : ""}
          </Text>
        </Row>
      )}
    </Stack>
  );
}
